<!doctype html>
<html lang="<?= \App\Core\Localization::current() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= \App\Core\t("Login history") ?> — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?php require __DIR__ . '/partials/language-switcher.php'; ?><main class="shell"><nav class="nav"><a class="brand" href="/dashboard">c0m.me</a><a class="nav-link" href="/sessions"><?= \App\Core\t("Active devices") ?></a></nav><section class="hero compact"><span class="eyebrow"><?= \App\Core\t("ACCOUNT SECURITY") ?></span><h1><?= \App\Core\t("Login history") ?></h1><p><?= \App\Core\t("Recent successful sign-ins associated with this account.") ?></p></section><section class="feature-grid" style="grid-template-columns:1fr"><?php foreach ($history as $item): ?><article><b><?= $item['success'] ? \App\Core\t('SUCCESSFUL SIGN-IN') : \App\Core\t('FAILED SIGN-IN') ?></b><p><?= htmlspecialchars($item['ip_display'], ENT_QUOTES, 'UTF-8') ?><br><?= htmlspecialchars($item['user_agent'] ?: 'Unknown browser', ENT_QUOTES, 'UTF-8') ?><br><?= htmlspecialchars($item['created_at'], ENT_QUOTES, 'UTF-8') ?></p></article><?php endforeach; ?><?php if (!$history): ?><article><p><?= \App\Core\t("No login history is available yet.") ?></p></article><?php endif; ?></section></main></body></html>
